public class QwikBiteApp extends JFrame {
    private final AuthDAO auth=new AuthDAO(); private final OrderDAO orders=new OrderDAO();
    private final CardLayout cards=new CardLayout(); private final JPanel root=new JPanel(cards); private Session session; private JComboBox<String> loginRole;
    public QwikBiteApp(){super("QwikBite | Campus food, delivered");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1180,790);setMinimumSize(new Dimension(1000,700));setLocationRelativeTo(null);root.setBackground(Style.IVORY);root.add(welcome(),"welcome");root.add(login(),"login");root.add(register(),"register");setContentPane(root);cards.show(root,"welcome");}
    private JPanel shell(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(20,20));p.setBackground(Style.IVORY);p.setBorder(new EmptyBorder(34,48,36,48));JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel brand=new JLabel("QwikBite");brand.setFont(new Font("Georgia",Font.BOLD,34));brand.setForeground(Style.OLIVE);top.add(brand,BorderLayout.WEST);JLabel tag=new JLabel("GOOD FOOD. CAMPUS SPEED.");tag.setForeground(Style.TERRACOTTA);tag.setFont(new Font("Segoe UI",Font.BOLD,11));top.add(tag,BorderLayout.EAST);p.add(top,BorderLayout.NORTH);JPanel body=new JPanel();body.setOpaque(false);body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel h=new JLabel(title);h.setFont(Style.TITLE.deriveFont(34f));h.setForeground(Style.OLIVE);JLabel s=new JLabel(subtitle);s.setForeground(new Color(110,108,98));s.setFont(Style.BODY);body.add(h);body.add(Box.createVerticalStrut(9));body.add(s);body.add(Box.createVerticalStrut(30));p.add(body,BorderLayout.CENTER);return p;}
    private JPanel welcome(){JPanel p=shell("Your campus cravings, sorted.","A better way to eat around campus. Pick a court, choose an outlet, and let a BiteMate bring it over.");JPanel body=(JPanel)p.getComponent(1);JPanel hero=new JPanel(new BorderLayout(20,10));hero.setBackground(Style.OLIVE);hero.setBorder(new EmptyBorder(28,30,28,30));JPanel copy=new JPanel();copy.setOpaque(false);copy.setLayout(new BoxLayout(copy,BoxLayout.Y_AXIS));JLabel eyebrow=new JLabel("THE CAMPUS FOOD CLUB");eyebrow.setForeground(new Color(225,177,139));eyebrow.setFont(new Font("Segoe UI",Font.BOLD,11));JLabel headline=new JLabel("<html>Good things are<br>closer than you think.</html>");headline.setForeground(Color.WHITE);headline.setFont(new Font("Georgia",Font.BOLD,30));JLabel desc=new JLabel("<html><div style='width:360px;color:#E6E0D3'>Twenty campus outlets. A whole lot of cravings. One simple checkout.</div></html>");desc.setFont(Style.BODY);copy.add(eyebrow);copy.add(Box.createVerticalStrut(16));copy.add(headline);copy.add(Box.createVerticalStrut(14));copy.add(desc);hero.add(copy,BorderLayout.CENTER);JLabel art=new JLabel("✦  🍜  ✦",SwingConstants.CENTER);art.setFont(new Font("Segoe UI Emoji",Font.PLAIN,48));art.setForeground(new Color(238,202,170));hero.add(art,BorderLayout.EAST);body.add(hero);body.add(Box.createVerticalStrut(24));JPanel actions=new JPanel(new GridLayout(1,2,14,0));actions.setOpaque(false);JButton login=Style.button("LOG IN",true),reg=Style.button("CREATE AN ACCOUNT",false);login.addActionListener(e->cards.show(root,"login"));reg.addActionListener(e->cards.show(root,"register"));actions.add(login);actions.add(reg);body.add(actions);body.add(Box.createVerticalStrut(24));JPanel info=new JPanel(new GridLayout(1,3,14,0));info.setOpaque(false);info.add(infoCard("01","Pick your court","Java Food Court or Vendhar Square."));info.add(infoCard("02","Choose an outlet","Browse the store and its full menu."));info.add(infoCard("03","Track the order","A clear confirmation and campus route preview."));body.add(info);return p;}
    private JPanel infoCard(String n,String h,String d){JPanel c=new JPanel();c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));c.setBackground(Style.SAND);c.setBorder(new EmptyBorder(18,20,18,20));JLabel a=new JLabel(n);a.setForeground(Style.TERRACOTTA);a.setFont(Style.HEADING);JLabel b=new JLabel(h);b.setForeground(Style.OLIVE);b.setFont(new Font("Segoe UI",Font.BOLD,15));JLabel x=new JLabel("<html><div style='width:190px'>"+d+"</div></html>");x.setForeground(new Color(95,94,86));c.add(a);c.add(Box.createVerticalStrut(9));c.add(b);c.add(Box.createVerticalStrut(7));c.add(x);return c;}
    private JPanel login(){
        JPanel p=shell("Welcome back.","Choose how you use QwikBite and sign in to continue.");
        JPanel body=(JPanel)p.getComponent(1); 
        loginRole=new JComboBox<>(new String[]{"STUDENT","FACULTY","STAFF","SHOP COUNTER","BITEMATE"});
        JTextField user=new JTextField();JPasswordField pass=new JPasswordField();
        JComboBox<String> court=new JComboBox<>();JComboBox<Object> shop=new JComboBox<>();configureShopSelectors(court,shop);
        JPanel form=new JPanel(new GridBagLayout());form.setBackground(Color.WHITE);
        form.setBorder(BorderFactory.createCompoundBorder(new javax.swing.border.LineBorder(new Color(226,220,207),1,true),new EmptyBorder(22,26,22,26)));
        GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(9,10,9,10);g.fill=GridBagConstraints.HORIZONTAL;g.anchor=GridBagConstraints.WEST;
        Runnable rebuild=()->{form.removeAll();int r=0;addAuthRow(form,g,r++,"ACCOUNT TYPE",loginRole);boolean isShop="SHOP COUNTER".equals(loginRole.getSelectedItem());
            if(isShop){addAuthRow(form,g,r++,"SELECT FOOD COURT",court);addAuthRow(form,g,r++,"SELECT SHOP",shop);}else addAuthRow(form,g,r++,"REGISTER NUMBER / USERNAME",user);
            addAuthRow(form,g,r,"PASSWORD",pass);form.revalidate();form.repaint();};
        loginRole.addActionListener(e->rebuild.run());rebuild.run();
        form.setMaximumSize(new Dimension(760,330));form.setAlignmentX(Component.LEFT_ALIGNMENT);body.add(form);body.add(Box.createVerticalStrut(18));
        JPanel row=actions(Style.button("SIGN IN",true),Style.button("BACK",false));body.add(row);
        ((JButton)row.getComponent(0)).addActionListener(e->{try{String selected=loginRole.getSelectedItem().toString();Session logged;
            if(selected.equals("SHOP COUNTER")){if(!(shop.getSelectedItem() instanceof OrderDAO.Shop chosen)){message("Select a food court first, then select your shop.");return;}logged=auth.login("SHOP","",new String(pass.getPassword()),chosen.id());}
            else{String dbRole=selected;logged=auth.login(dbRole,user.getText(),new String(pass.getPassword()));}
            if(logged==null){message("Login details are incorrect or the selected shop password does not match.");return;}session=logged;showDashboard();
        }catch(SQLException ex){error(ex);}});
        ((JButton)row.getComponent(1)).addActionListener(e->cards.show(root,"welcome"));return p;
    }
    private void configureShopSelectors(JComboBox<String> court,JComboBox<Object> shop){
        court.removeAllItems();court.addItem("Select food court");shop.removeAllItems();shop.addItem("Select shop");
        try{for(String name:auth.foodCourts())court.addItem(name);}catch(SQLException ex){error(ex);}
        court.addActionListener(e->{shop.removeAllItems();shop.addItem("Select shop");Object selected=court.getSelectedItem();if(selected==null||selected.toString().equals("Select food court"))return;
            try{for(OrderDAO.Shop item:auth.shopsForCourt(selected.toString()))shop.addItem(item);}catch(SQLException ex){error(ex);}
        });
    }
    private void addAuthRow(JPanel form,GridBagConstraints g,int row,String label,JComponent input){
        g.gridy=row;g.gridx=0;g.weightx=0;g.ipadx=0;JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,11));l.setForeground(Style.OLIVE);l.setPreferredSize(new Dimension(205,38));form.add(l,g);
        g.gridx=1;g.weightx=1;input.setPreferredSize(new Dimension(390,40));input.setMinimumSize(new Dimension(280,40));if(input instanceof JTextField f)Style.field(f);if(input instanceof JPasswordField f)Style.field(f);form.add(input,g);
    }
    private JPanel register(){
        JPanel p=shell("Join the campus table.","Create a student, staff, BiteMate or shop counter account.");
        JPanel body=(JPanel)p.getComponent(1);
        JComboBox<String> type=new JComboBox<>(new String[]{"STUDENT","FACULTY","STAFF","BITEMATE","SHOP COUNTER"});
        JPanel form=new JPanel(new GridBagLayout());form.setOpaque(true);form.setBackground(Color.WHITE);
        form.setBorder(BorderFactory.createCompoundBorder(new javax.swing.border.LineBorder(new Color(226,220,207),1,true),new EmptyBorder(20,24,20,24)));
        form.setMaximumSize(new Dimension(780,470));form.setAlignmentX(Component.LEFT_ALIGNMENT);
        JTextField id=new JTextField(),name=new JTextField(),phone=new JTextField();JPasswordField password=new JPasswordField();
        JComboBox<String> court=new JComboBox<>();JComboBox<Object> shop=new JComboBox<>();configureShopSelectors(court,shop);
        Runnable rebuild=()->{form.removeAll();GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(6,8,6,8);g.fill=GridBagConstraints.HORIZONTAL;g.anchor=GridBagConstraints.WEST;int r=0;addSignupRow(form,g,r++,"ACCOUNT TYPE",type);String selected=type.getSelectedItem().toString();
            if(selected.equals("STUDENT")||selected.equals("FACULTY")||selected.equals("STAFF")){addSignupRow(form,g,r++,"REGISTER NUMBER / STAFF ID",id);addSignupRow(form,g,r++,"FULL NAME",name);addSignupRow(form,g,r++,"PHONE NUMBER",phone);}
            else if(selected.equals("BITEMATE")){addSignupRow(form,g,r++,"FULL NAME",name);addSignupRow(form,g,r++,"USERNAME",id);}
            else{addSignupRow(form,g,r++,"SELECT FOOD COURT",court);addSignupRow(form,g,r++,"SELECT SHOP",shop);}
            addSignupRow(form,g,r,"PASSWORD (MINIMUM 6 CHARACTERS)",password);form.revalidate();form.repaint();};
        type.addActionListener(e->rebuild.run());rebuild.run();body.add(form);body.add(Box.createVerticalStrut(16));
        JPanel row=actions(Style.button("CREATE ACCOUNT",true),Style.button("BACK",false));body.add(row);
        ((JButton)row.getComponent(0)).addActionListener(e->{String selected=type.getSelectedItem().toString(),pw=new String(password.getPassword());if(pw.length()<6){message("Password must contain at least 6 characters.");return;}
            try{if(selected.equals("STUDENT")||selected.equals("FACULTY")||selected.equals("STAFF")){if(id.getText().isBlank()||name.getText().isBlank()||phone.getText().isBlank()){message("Complete every field before creating the account.");return;}auth.register(id.getText(),name.getText(),phone.getText(),pw,selected);}
                else if(selected.equals("BITEMATE")){if(id.getText().isBlank()||name.getText().isBlank()){message("Enter your full name and username.");return;}auth.registerBiteMate(name.getText(),id.getText(),pw);}
                else{if(!(shop.getSelectedItem() instanceof OrderDAO.Shop chosen)){message("Select a food court first, then select your shop.");return;}auth.registerShop(chosen.id(),pw);}
                message("Account created successfully. You can now log in.");if(loginRole!=null)loginRole.setSelectedItem(selected.equals("SHOP COUNTER")?"SHOP COUNTER":selected);cards.show(root,"login");
            }catch(SQLException ex){error(ex);}});
        ((JButton)row.getComponent(1)).addActionListener(e->cards.show(root,"welcome"));return p;
    }
    private void addSignupRow(JPanel form,GridBagConstraints g,int row,String label,JComponent input){
        g.gridy=row;g.gridx=0;g.weightx=0;JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,10));l.setForeground(Style.OLIVE);l.setPreferredSize(new Dimension(235,36));form.add(l,g);
        g.gridx=1;g.weightx=1;input.setPreferredSize(new Dimension(390,38));input.setMinimumSize(new Dimension(250,38));if(input instanceof JTextField f)Style.field(f);if(input instanceof JPasswordField f)Style.field(f);form.add(input,g);
    }
    private JPanel actions(JButton a,JButton b){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));p.setOpaque(false);p.add(a);p.add(b);return p;}
    private void addFormRow(JPanel p,String label,JComponent input){JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,11));l.setForeground(Style.OLIVE);input.setMaximumSize(new Dimension(460,40));input.setPreferredSize(new Dimension(420,38));if(input instanceof JTextField f)Style.field(f);if(input instanceof JPasswordField f)Style.field(f);p.add(l);p.add(Box.createVerticalStrut(5));p.add(input);p.add(Box.createVerticalStrut(12));}
    private void showDashboard(){root.add(dashboard(),"dashboard");cards.show(root,"dashboard");}
    private JPanel dashboard(){JPanel p=new JPanel(new BorderLayout());p.setBackground(Style.IVORY);JPanel bar=new JPanel(new BorderLayout());bar.setBackground(Style.OLIVE);bar.setBorder(new EmptyBorder(16,26,16,26));JLabel brand=new JLabel("QwikBite   /   "+session.role());brand.setForeground(Color.WHITE);brand.setFont(Style.HEADING);JButton logout=Style.button("LOG OUT",false);logout.addActionListener(e->{session=null;cards.show(root,"welcome");});bar.add(brand,BorderLayout.WEST);bar.add(logout,BorderLayout.EAST);p.add(bar,BorderLayout.NORTH);JPanel content=new JPanel(new BorderLayout(12,12));content.setBackground(Style.IVORY);content.setBorder(new EmptyBorder(25,30,28,30));JLabel welcome=new JLabel("Hello, "+session.name());welcome.setFont(Style.TITLE);welcome.setForeground(Style.OLIVE);content.add(welcome,BorderLayout.NORTH);if(session.role().equals("STUDENT")||session.role().equals("FACULTY")||session.role().equals("STAFF"))studentPanel(content);else if(session.role().equals("SHOP"))shopPanel(content);else biteMatePanel(content);p.add(content,BorderLayout.CENTER);return p;}
    private void studentPanel(JPanel parent){JPanel wrap=new JPanel(new BorderLayout(14,14));wrap.setOpaque(false);JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("Segoe UI",Font.BOLD,13));tabs.addTab("ORDER FOOD",orderPanel());tabs.addTab("ORDER HISTORY",historyPanel());wrap.add(tabs,BorderLayout.CENTER);parent.add(wrap,BorderLayout.CENTER);}
    private static class CartLine { final OrderDAO.MenuItem item; int quantity; CartLine(OrderDAO.MenuItem item){this.item=item;this.quantity=1;} }
    private JPanel orderPanel(){
        JPanel page=new JPanel(new BorderLayout(18,18));page.setOpaque(false);
        JPanel top=new JPanel(new BorderLayout(12,10));top.setOpaque(false);
        JPanel selectors=new JPanel(new GridLayout(1,3,12,0));selectors.setOpaque(false);
        JComboBox<String> court=new JComboBox<>(new String[]{"Java Food Court","Vendhar Square"});
        JComboBox<OrderDAO.Shop> shop=new JComboBox<>();JComboBox<String> building=new JComboBox<>(new String[]{"TP1","TP2","UB"});
        JTextField floor=new JTextField("1"),room=new JTextField();
        selectors.add(fieldBox("01  FOOD COURT",court));selectors.add(fieldBox("02  CHOOSE AN OUTLET",shop));selectors.add(fieldBox("03  DELIVERY BUILDING",building));top.add(selectors,BorderLayout.CENTER);
        JPanel address=new JPanel(new GridLayout(1,2,12,0));address.setOpaque(false);address.add(fieldBox("FLOOR",floor));address.add(fieldBox("ROOM NUMBER",room));top.add(address,BorderLayout.SOUTH);page.add(top,BorderLayout.NORTH);
        JPanel menuArea=new JPanel(new BorderLayout(8,8));menuArea.setOpaque(false);
        JPanel menuHeading=new JPanel(new BorderLayout());menuHeading.setOpaque(false);
        JLabel heading=Style.heading("Made for your next craving");heading.setFont(new Font("Georgia",Font.BOLD,24));
        JLabel caption=new JLabel("Choose an outlet, add your favourites, then checkout in one go.");caption.setForeground(new Color(115,111,101));
        JPanel headingStack=new JPanel();headingStack.setOpaque(false);headingStack.setLayout(new BoxLayout(headingStack,BoxLayout.Y_AXIS));headingStack.add(heading);headingStack.add(Box.createVerticalStrut(5));headingStack.add(caption);menuHeading.add(headingStack,BorderLayout.WEST);menuArea.add(menuHeading,BorderLayout.NORTH);
        JPanel menuGrid=new JPanel(new GridLayout(0,2,14,14));menuGrid.setBackground(Style.IVORY);JScrollPane scroller=new JScrollPane(menuGrid);scroller.setBorder(BorderFactory.createEmptyBorder());scroller.getViewport().setBackground(Style.IVORY);scroller.getVerticalScrollBar().setUnitIncrement(18);menuArea.add(scroller,BorderLayout.CENTER);page.add(menuArea,BorderLayout.CENTER);
        LinkedHashMap<Integer,CartLine> cart=new LinkedHashMap<>();
        JButton cartButton=Style.button("VIEW CART  ·  0 ITEMS",false);JButton floatingOrder=Style.button("PLACE ORDER  →  0 ITEMS",true);floatingOrder.setFont(new Font("Segoe UI",Font.BOLD,14));
        Runnable updateCartButton=()->{int count=cart.values().stream().mapToInt(x->x.quantity).sum();cartButton.setText("🛒  VIEW CART · "+count+" ITEMS");floatingOrder.setText("PLACE ORDER  →  "+count+" ITEMS");floatingOrder.setEnabled(count>0);};
        Runnable[] loadMenuRef=new Runnable[1];
        Runnable loadMenu=()->{menuGrid.removeAll();OrderDAO.Shop selected=(OrderDAO.Shop)shop.getSelectedItem();if(selected==null){menuGrid.revalidate();menuGrid.repaint();return;}try{
            List<OrderDAO.MenuItem> items=orders.menuForShop(selected.id());
            if(items.isEmpty()){JLabel empty=new JLabel("This outlet has no available items right now.");empty.setForeground(Style.OLIVE);menuGrid.add(empty);}
            for(OrderDAO.MenuItem item:items){
                JPanel card=new JPanel(new BorderLayout(10,8));card.setBackground(Color.WHITE);card.setBorder(BorderFactory.createCompoundBorder(new javax.swing.border.LineBorder(new Color(225,219,207),1,true),new EmptyBorder(15,16,15,16)));
                JPanel visual=new JPanel(new BorderLayout());visual.setBackground(new Color(239,231,215));visual.setPreferredSize(new Dimension(90,84));JLabel emoji=new JLabel(foodGlyph(item.name()),SwingConstants.CENTER);emoji.setFont(new Font("Segoe UI Emoji",Font.PLAIN,34));visual.add(emoji,BorderLayout.CENTER);card.add(visual,BorderLayout.WEST);
                JPanel details=new JPanel();details.setOpaque(false);details.setLayout(new BoxLayout(details,BoxLayout.Y_AXIS));JLabel name=new JLabel(item.name());name.setFont(new Font("Segoe UI",Font.BOLD,15));name.setForeground(Style.OLIVE);JLabel desc=new JLabel("<html><div style='width:230px;color:#77736A'>"+escapeHtml(item.description())+"</div></html>");desc.setFont(new Font("Segoe UI",Font.PLAIN,11));JLabel price=new JLabel(String.format("₹%.2f",item.price()));price.setFont(new Font("Segoe UI",Font.BOLD,16));price.setForeground(Style.TERRACOTTA);details.add(name);details.add(Box.createVerticalStrut(5));details.add(desc);details.add(Box.createVerticalStrut(8));details.add(price);card.add(details,BorderLayout.CENTER);
                JPanel action=new JPanel(new FlowLayout(FlowLayout.RIGHT,4,0));action.setOpaque(false);CartLine line=cart.get(item.id());
                if(line==null){JButton add=Style.button("ADD +",true);add.addActionListener(e->{CartLine current=cart.get(item.id());if(current==null)cart.put(item.id(),new CartLine(item));else current.quantity++;updateCartButton.run();loadMenuRef[0].run();});action.add(add);}
                else{JButton minus=Style.button("−",false),plus=Style.button("+",true);JLabel qty=new JLabel(String.valueOf(line.quantity));qty.setFont(new Font("Segoe UI",Font.BOLD,14));minus.addActionListener(e->{CartLine current=cart.get(item.id());if(current!=null){current.quantity--;if(current.quantity<=0)cart.remove(item.id());}updateCartButton.run();loadMenuRef[0].run();});plus.addActionListener(e->{CartLine current=cart.get(item.id());if(current!=null)current.quantity++;updateCartButton.run();loadMenuRef[0].run();});action.add(minus);action.add(qty);action.add(plus);}card.add(action,BorderLayout.SOUTH);menuGrid.add(card);
            }
        }catch(SQLException ex){error(ex);}menuGrid.revalidate();menuGrid.repaint();};
        loadMenuRef[0]=loadMenu;
        court.addActionListener(e->{cart.clear();updateCartButton.run();loadShops(court,shop,loadMenu);});shop.addActionListener(e->{cart.clear();updateCartButton.run();loadMenuRef[0].run();});
        cartButton.addActionListener(e->showCartDialog(cart,cartButton,building,floor,room,()->{updateCartButton.run();loadMenuRef[0].run();}));
        floatingOrder.addActionListener(e->showCheckoutBill(cart,building,floor,room,()->{updateCartButton.run();loadMenuRef[0].run();}));
        JPanel sticky=new JPanel(new BorderLayout(12,0));sticky.setBackground(Color.WHITE);sticky.setBorder(new EmptyBorder(12,16,12,16));JLabel hint=new JLabel("Your cart stays with this outlet while you browse.");hint.setForeground(Style.MUTED);sticky.add(hint,BorderLayout.WEST);sticky.add(cartButton,BorderLayout.CENTER);sticky.add(floatingOrder,BorderLayout.EAST);page.add(sticky,BorderLayout.SOUTH);
        updateCartButton.run();loadShops(court,shop,loadMenu);return page;
    }
    private void loadShops(JComboBox<String> court,JComboBox<OrderDAO.Shop> shop,Runnable loadMenu){try{shop.removeAllItems();for(OrderDAO.Shop s:orders.shops(court.getSelectedItem().toString()))shop.addItem(s);loadMenu.run();}catch(SQLException ex){error(ex);}}
    private String foodGlyph(String name){String n=name.toLowerCase();if(n.contains("pizza"))return "🍕";if(n.contains("biryani")||n.contains("rice"))return "🍛";if(n.contains("coffee")||n.contains("tea"))return "☕";if(n.contains("burger"))return "🍔";if(n.contains("dosa")||n.contains("idli"))return "🥘";if(n.contains("juice")||n.contains("soda"))return "🥤";if(n.contains("shawarma")||n.contains("roll"))return "🌯";if(n.contains("chicken"))return "🍗";return "🍽";}
    private String escapeHtml(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    private void showCartDialog(LinkedHashMap<Integer,CartLine> cart,JButton cartButton,JComboBox<String> building,JTextField floor,JTextField room,Runnable changed){
        JDialog dialog=new JDialog(this,"Your QwikBite cart",true);dialog.setSize(760,620);dialog.setMinimumSize(new Dimension(680,540));dialog.setLocationRelativeTo(this);
        JPanel base=new JPanel(new BorderLayout(16,16));base.setBackground(Style.IVORY);base.setBorder(new EmptyBorder(22,24,22,24));
        JPanel heading=new JPanel(new BorderLayout());heading.setOpaque(false);JLabel title=new JLabel("Your cart");title.setFont(new Font("Georgia",Font.BOLD,28));title.setForeground(Style.OLIVE);JLabel subtitle=new JLabel("Review your picks before checkout.");subtitle.setForeground(new Color(115,111,101));JPanel labels=new JPanel();labels.setOpaque(false);labels.setLayout(new BoxLayout(labels,BoxLayout.Y_AXIS));labels.add(title);labels.add(Box.createVerticalStrut(4));labels.add(subtitle);heading.add(labels,BorderLayout.WEST);base.add(heading,BorderLayout.NORTH);
        DefaultTableModel model=new DefaultTableModel(new String[]{"ITEM","UNIT PRICE","QTY","LINE TOTAL",""},0){public boolean isCellEditable(int r,int c){return false;}};JTable table=new JTable(model);table.setRowHeight(38);table.setFont(new Font("Segoe UI",Font.PLAIN,13));table.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,11));JScrollPane scroll=new JScrollPane(table);scroll.setBorder(BorderFactory.createLineBorder(new Color(225,219,207)));base.add(scroll,BorderLayout.CENTER);
        JPanel bottom=new JPanel(new BorderLayout(10,10));bottom.setOpaque(false);JPanel totalPanel=new JPanel(new FlowLayout(FlowLayout.LEFT,10,4));totalPanel.setOpaque(false);JLabel subtotalLabel=new JLabel();subtotalLabel.setFont(new Font("Segoe UI",Font.BOLD,15));subtotalLabel.setForeground(Style.OLIVE);totalPanel.add(subtotalLabel);bottom.add(totalPanel,BorderLayout.NORTH);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);JButton viewBill=Style.button("VIEW BILL & CHECKOUT",true),close=Style.button("CONTINUE SHOPPING",false);actions.add(viewBill);actions.add(close);bottom.add(actions,BorderLayout.SOUTH);base.add(bottom,BorderLayout.SOUTH);
        Runnable refresh=()->{model.setRowCount(0);double subtotal=0;int count=0;for(CartLine line:cart.values()){double lineTotal=line.item.price()*line.quantity;subtotal+=lineTotal;count+=line.quantity;model.addRow(new Object[]{line.item.name(),String.format("₹%.2f",line.item.price()),line.quantity,String.format("₹%.2f",lineTotal),"Use − / + below"});}subtotalLabel.setText("ITEMS: "+count+"     SUBTOTAL: "+String.format("₹%.2f",subtotal));viewBill.setEnabled(!cart.isEmpty());};refresh.run();
        JPanel qtyActions=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0));qtyActions.setOpaque(false);JButton minus=Style.button("− REMOVE ONE",false),plus=Style.button("+ ADD ONE",false),remove=Style.button("REMOVE ITEM",false);qtyActions.add(minus);qtyActions.add(plus);qtyActions.add(remove);bottom.add(qtyActions,BorderLayout.CENTER);
        java.util.function.Supplier<Integer> selectedId=()->{int row=table.getSelectedRow();if(row<0)return null;String name=model.getValueAt(row,0).toString();for(CartLine line:cart.values())if(line.item.name().equals(name))return line.item.id();return null;};
        minus.addActionListener(e->{Integer id=selectedId.get();if(id==null){message("Select an item first.");return;}CartLine line=cart.get(id);if(--line.quantity<=0)cart.remove(id);refresh.run();changed.run();});plus.addActionListener(e->{Integer id=selectedId.get();if(id==null){message("Select an item first.");return;}cart.get(id).quantity++;refresh.run();changed.run();});remove.addActionListener(e->{Integer id=selectedId.get();if(id==null){message("Select an item first.");return;}cart.remove(id);refresh.run();changed.run();});
        viewBill.addActionListener(e->{dialog.dispose();showCheckoutBill(cart,building,floor,room,changed);});
        close.addActionListener(e->dialog.dispose());
        dialog.setContentPane(base);dialog.setVisible(true);
    }
    private void showCheckoutBill(LinkedHashMap<Integer,CartLine> cart,JComboBox<String> building,JTextField floor,JTextField room,Runnable changed){
        if(cart.isEmpty()){message("Your cart is empty. Add something delicious first.");return;}
        final int fl;try{fl=Integer.parseInt(floor.getText().trim());if(fl<0)throw new NumberFormatException();}catch(NumberFormatException ex){message("Enter a valid floor number before checkout.");return;}
        if(room.getText().isBlank()){message("Enter your room number before checkout.");return;}
        double subtotal=cart.values().stream().mapToDouble(x->x.item.price()*x.quantity).sum();double delivery=fl<=4?10:10+(fl-4);double total=subtotal+delivery;
        JDialog bill=new JDialog(this,"Review your bill",true);bill.setSize(650,620);bill.setMinimumSize(new Dimension(580,540));bill.setLocationRelativeTo(this);
        JPanel base=new JPanel(new BorderLayout(16,16));base.setBackground(Style.IVORY);base.setBorder(new EmptyBorder(24,28,24,28));
        JLabel title=new JLabel("Your order, itemised.");title.setFont(new Font("Georgia",Font.BOLD,28));title.setForeground(Style.OLIVE);JLabel sub=new JLabel("Review the fare breakup before placing your order.");sub.setForeground(Style.MUTED);JPanel head=new JPanel();head.setOpaque(false);head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.add(title);head.add(Box.createVerticalStrut(5));head.add(sub);base.add(head,BorderLayout.NORTH);
        JPanel rows=new JPanel();rows.setBackground(Color.WHITE);rows.setBorder(new EmptyBorder(16,18,16,18));rows.setLayout(new BoxLayout(rows,BoxLayout.Y_AXIS));
        for(CartLine line:cart.values())addBillRow(rows,line.item.name()+"  ×  "+line.quantity,String.format("₹%.2f",line.item.price()*line.quantity),false);
        rows.add(new JSeparator());addBillRow(rows,"Food subtotal",String.format("₹%.2f",subtotal),false);addBillRow(rows,"Delivery fee · Floor "+fl,String.format("₹%.2f",delivery),false);addBillRow(rows,"Convenience fee","₹0.00",false);addBillRow(rows,"Taxes","Included in listed prices",false);rows.add(Box.createVerticalStrut(8));addBillRow(rows,"TOTAL PAYABLE",String.format("₹%.2f",total),true);
        JPanel deliveryInfo=new JPanel(new FlowLayout(FlowLayout.LEFT,4,0));deliveryInfo.setOpaque(false);deliveryInfo.add(new JLabel("Deliver to: "+building.getSelectedItem()+" · Floor "+fl+" · Room "+room.getText().trim()));rows.add(Box.createVerticalStrut(12));rows.add(deliveryInfo);
        base.add(rows,BorderLayout.CENTER);
        JPanel bottom=new JPanel(new BorderLayout(8,8));bottom.setOpaque(false);JLabel payNote=new JLabel("Payment is collected by your BiteMate at delivery.");payNote.setForeground(Style.OLIVE);bottom.add(payNote,BorderLayout.NORTH);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));buttons.setOpaque(false);JButton back=Style.button("BACK TO CART",false),place=Style.button("PLACE ORDER  →",true);buttons.add(back);buttons.add(place);bottom.add(buttons,BorderLayout.SOUTH);base.add(bottom,BorderLayout.SOUTH);
        back.addActionListener(e->bill.dispose());place.addActionListener(e->{Object[] choices={"Cash to BiteMate","UPI to BiteMate"};int selected=JOptionPane.showOptionDialog(bill,"Choose how you will pay your BiteMate when the order is delivered.","Payment at delivery",JOptionPane.DEFAULT_OPTION,JOptionPane.QUESTION_MESSAGE,null,choices,choices[0]);if(selected<0)return;String method=selected==0?"CASH_ON_DELIVERY":"UPI_ON_DELIVERY";try{List<OrderDAO.CartItem> items=new ArrayList<>();for(CartLine line:cart.values())items.add(new OrderDAO.CartItem(line.item.id(),line.quantity));int orderId=orders.placeOrder(session.id(),items,building.getSelectedItem().toString(),fl,room.getText().trim(),method);cart.clear();changed.run();bill.dispose();showOrderSuccess(orderId,subtotal,delivery,building.getSelectedItem().toString(),fl,room.getText().trim(),selected==0?"Cash to BiteMate":"UPI to BiteMate");}catch(SQLException|IllegalArgumentException ex){message(ex.getMessage());}});
        bill.setContentPane(base);bill.setVisible(true);
    }
    private void addBillRow(JPanel panel,String left,String right,boolean total){JPanel row=new JPanel(new BorderLayout());row.setOpaque(false);JLabel l=new JLabel(left),r=new JLabel(right);l.setFont(new Font("Segoe UI",total?Font.BOLD:Font.PLAIN,total?16:13));r.setFont(new Font("Segoe UI",total?Font.BOLD:Font.PLAIN,total?17:13));l.setForeground(Style.OLIVE);r.setForeground(total?Style.TERRACOTTA:Style.INK);row.add(l,BorderLayout.WEST);row.add(r,BorderLayout.EAST);row.setMaximumSize(new Dimension(Integer.MAX_VALUE,34));panel.add(row);}
    private JPanel fieldBox(String label,JComponent component){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,10));l.setForeground(Style.OLIVE);if(component instanceof JTextField f)Style.field(f);component.setMaximumSize(new Dimension(Integer.MAX_VALUE,38));p.add(l);p.add(Box.createVerticalStrut(5));p.add(component);return p;}
    private JPanel cardPanel(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(226,220,207)),new EmptyBorder(16,18,16,18)));return p;}
    private JPanel historyPanel(){JPanel p=new JPanel(new BorderLayout(10,10));p.setOpaque(false);DefaultTableModel m=new DefaultTableModel(new String[]{"ORDER","OUTLET","ITEM","QTY","BUILDING","FLOOR","ROOM","TOTAL ₹","STATUS","PLACED"},0){public boolean isCellEditable(int r,int c){return false;}};JTable t=new JTable(m);t.setRowHeight(34);JButton refresh=Style.button("REFRESH HISTORY",false);refresh.addActionListener(e->{try{m.setRowCount(0);for(Object[] r:orders.history(session.id()))m.addRow(r);}catch(SQLException ex){error(ex);}});p.add(refresh,BorderLayout.NORTH);p.add(new JScrollPane(t),BorderLayout.CENTER);refresh.doClick();return p;}
    private void showOrderSuccess(int id,double subtotal,double fee,String building,int floor,String room,String paymentMethod){JDialog d=new JDialog(this,"Order placed",true);d.setSize(690,620);d.setLocationRelativeTo(this);JPanel p=new JPanel();p.setBackground(Style.IVORY);p.setBorder(new EmptyBorder(25,30,25,30));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel tick=new JLabel("✓",SwingConstants.CENTER);tick.setOpaque(true);tick.setBackground(new Color(43,132,82));tick.setForeground(Color.WHITE);tick.setFont(new Font("Segoe UI",Font.BOLD,42));tick.setAlignmentX(Component.CENTER_ALIGNMENT);tick.setPreferredSize(new Dimension(76,76));tick.setMaximumSize(new Dimension(76,76));JLabel title=new JLabel("Your order is placed!");title.setFont(new Font("Georgia",Font.BOLD,28));title.setForeground(Style.OLIVE);title.setAlignmentX(Component.CENTER_ALIGNMENT);JLabel sub=new JLabel("Order #"+id+"  ·  "+paymentMethod+" at delivery");sub.setForeground(new Color(110,108,98));sub.setAlignmentX(Component.CENTER_ALIGNMENT);p.add(tick);p.add(Box.createVerticalStrut(14));p.add(title);p.add(Box.createVerticalStrut(7));p.add(sub);p.add(Box.createVerticalStrut(18));JPanel map=new MapPreview(building,floor,room);map.setPreferredSize(new Dimension(610,245));map.setMaximumSize(new Dimension(610,245));p.add(map);p.add(Box.createVerticalStrut(15));JLabel total=new JLabel(String.format("Food ₹%.2f     Delivery ₹%.2f     Total ₹%.2f",subtotal,fee,subtotal+fee));total.setFont(new Font("Segoe UI",Font.BOLD,15));total.setForeground(Style.OLIVE);total.setAlignmentX(Component.CENTER_ALIGNMENT);p.add(total);p.add(Box.createVerticalStrut(10));JLabel note=new JLabel("Map preview is illustrative only. Live GPS tracking is not enabled.");note.setFont(new Font("Segoe UI",Font.ITALIC,11));note.setForeground(new Color(120,115,103));note.setAlignmentX(Component.CENTER_ALIGNMENT);p.add(note);p.add(Box.createVerticalStrut(15));JButton close=Style.button("DONE",true);close.setAlignmentX(Component.CENTER_ALIGNMENT);close.addActionListener(e->d.dispose());p.add(close);d.setContentPane(p);d.setVisible(true);}
    private static class MapPreview extends JPanel {private final String building;private final int floor;private final String room;MapPreview(String b,int f,String r){building=b;floor=f;room=r;setOpaque(true);setBackground(new Color(235,232,218));setBorder(BorderFactory.createLineBorder(new Color(211,204,187)));}protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D x=(Graphics2D)g.create();x.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);x.setColor(new Color(216,224,205));for(int i=0;i<getWidth();i+=70)x.fillRect(i,0,28,getHeight());x.setColor(new Color(250,248,239));x.setStroke(new BasicStroke(18));x.drawLine(25,getHeight()-35,getWidth()-30,35);x.drawLine(100,20,getWidth()-80,getHeight()-20);x.setColor(new Color(190,203,179));x.setStroke(new BasicStroke(2));for(int i=0;i<getWidth();i+=110)x.drawLine(i,0,i+40,getHeight());int px=getWidth()/2,py=getHeight()/2;x.setColor(Style.TERRACOTTA);x.fillOval(px-14,py-14,28,28);x.setColor(Color.WHITE);x.fillOval(px-5,py-5,10,10);x.setColor(Style.OLIVE);x.setFont(new Font("Segoe UI",Font.BOLD,15));x.drawString("DELIVERY DESTINATION",22,28);x.setFont(new Font("Segoe UI",Font.BOLD,13));x.drawString(building+"  ·  Floor "+floor+"  ·  Room "+room,22,getHeight()-18);x.dispose();}}
    private void shopPanel(JPanel parent){
        JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("Segoe UI",Font.BOLD,13));
        JPanel ordersTab=new JPanel(new BorderLayout(10,10));ordersTab.setOpaque(false);
        DefaultTableModel om=new DefaultTableModel(new String[]{"ORDER","BUILDING","FLOOR","ROOM","TOTAL ₹","STATUS","CREATED"},0){public boolean isCellEditable(int r,int c){return false;}};
        JTable ot=new JTable(om);ot.setRowHeight(32);JButton refreshO=Style.button("REFRESH ORDERS",false),accept=Style.button("ACCEPT ORDER",true),ready=Style.button("MARK READY FOR PICKUP",true),reject=Style.button("REJECT",false);
        JPanel ob=new JPanel(new FlowLayout(FlowLayout.LEFT,8,6));ob.setOpaque(false);ob.add(refreshO);ob.add(accept);ob.add(ready);ob.add(reject);
        refreshO.addActionListener(e->{try{om.setRowCount(0);for(Object[] r:orders.ordersForShop(session.id()))om.addRow(r);}catch(SQLException ex){error(ex);}});
        accept.addActionListener(e->changeSelected(ot,om,"ACCEPTED"));ready.addActionListener(e->changeSelected(ot,om,"READY"));reject.addActionListener(e->changeSelected(ot,om,"REJECTED"));
        ordersTab.add(ob,BorderLayout.NORTH);ordersTab.add(new JScrollPane(ot),BorderLayout.CENTER);
        JPanel inventoryTab=new JPanel(new BorderLayout(10,10));inventoryTab.setOpaque(false);
        DefaultTableModel im=new DefaultTableModel(new String[]{"ID","ITEM","DESCRIPTION","PRICE ₹","STOCK","AVAILABLE"},0){public boolean isCellEditable(int r,int c){return false;}};
        JTable it=new JTable(im);it.setRowHeight(31);it.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        JButton refreshI=Style.button("REFRESH STOCK",false),add=Style.button("ADD ITEM",true),edit=Style.button("EDIT SELECTED",false),availability=Style.button("TOGGLE AVAILABLE",false),shopToggle=Style.button("TOGGLE SHOP OPEN / CLOSED",false);
        JPanel ib=new JPanel(new FlowLayout(FlowLayout.LEFT,8,6));ib.setOpaque(false);ib.add(refreshI);ib.add(add);ib.add(edit);ib.add(availability);ib.add(shopToggle);
        Runnable loadInventory=()->{try{im.setRowCount(0);for(OrderDAO.InventoryItem x:orders.inventoryForShop(session.id()))im.addRow(new Object[]{x.id(),x.name(),x.description(),String.format("%.2f",x.price()),x.stock(),x.available()?"YES":"NO"});}catch(SQLException ex){error(ex);}};
        refreshI.addActionListener(e->loadInventory.run());
        java.util.function.Consumer<Integer> editItem=(id)->{String name=JOptionPane.showInputDialog(this,"Food item name:",id>0?String.valueOf(im.getValueAt(it.getSelectedRow(),1)):"");if(name==null)return;String desc=JOptionPane.showInputDialog(this,"Description:",id>0?String.valueOf(im.getValueAt(it.getSelectedRow(),2)):"");if(desc==null)return;String price=JOptionPane.showInputDialog(this,"Price (₹):",id>0?String.valueOf(im.getValueAt(it.getSelectedRow(),3)):"99");if(price==null)return;String stock=JOptionPane.showInputDialog(this,"Stock quantity:",id>0?String.valueOf(im.getValueAt(it.getSelectedRow(),4)):"20");if(stock==null)return;try{double pv=Double.parseDouble(price);int sv=Integer.parseInt(stock);orders.saveInventoryItem(session.id(),id,name,desc,pv,sv,true);loadInventory.run();message("Inventory saved.");}catch(NumberFormatException ex){message("Enter a valid numeric price and stock quantity.");}catch(SQLException|IllegalArgumentException ex){message(ex.getMessage());}};
        add.addActionListener(e->editItem.accept(0));edit.addActionListener(e->{int r=it.getSelectedRow();if(r<0){message("Select a menu item first.");return;}editItem.accept(Integer.parseInt(im.getValueAt(r,0).toString()));});
        availability.addActionListener(e->{int r=it.getSelectedRow();if(r<0){message("Select a menu item first.");return;}try{int id=Integer.parseInt(im.getValueAt(r,0).toString());OrderDAO.InventoryItem old=orders.inventoryForShop(session.id()).stream().filter(x->x.id()==id).findFirst().orElseThrow();orders.saveInventoryItem(session.id(),id,old.name(),old.description(),old.price(),old.stock(),!old.available());loadInventory.run();}catch(Exception ex){message(ex.getMessage());}});
        shopToggle.addActionListener(e->{Object[] opts={"OPEN","CLOSED"};int v=JOptionPane.showOptionDialog(this,"Set your outlet status","Shop availability",JOptionPane.DEFAULT_OPTION,JOptionPane.QUESTION_MESSAGE,null,opts,opts[0]);if(v>=0)try{orders.setShopOpen(session.id(),v==0);message("Shop status updated.");}catch(SQLException ex){error(ex);}});
        inventoryTab.add(ib,BorderLayout.NORTH);inventoryTab.add(new JScrollPane(it),BorderLayout.CENTER);
        tabs.addTab("ORDER QUEUE",ordersTab);tabs.addTab("MENU & INVENTORY",inventoryTab);parent.add(tabs,BorderLayout.CENTER);refreshO.doClick();loadInventory.run();
    }
    private void biteMatePanel(JPanel parent){
        JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("Segoe UI",Font.BOLD,13));
        JPanel poolTab=new JPanel(new BorderLayout(10,10));poolTab.setOpaque(false);
        DefaultTableModel pm=new DefaultTableModel(new String[]{"ORDER","OUTLET","BUILDING","FLOOR","ROOM","TOTAL ₹","SHOP STATUS","PLACED"},0){public boolean isCellEditable(int r,int c){return false;}};JTable pt=new JTable(pm);pt.setRowHeight(32);
        JButton refreshP=Style.button("REFRESH NEW ORDERS",false),details=Style.button("VIEW FULL ORDER",false),claim=Style.button("ACCEPT ORDER",true),decline=Style.button("DECLINE ORDER",false);
        JPanel pb=new JPanel(new FlowLayout(FlowLayout.LEFT));pb.setOpaque(false);pb.add(refreshP);pb.add(details);pb.add(claim);pb.add(decline);
        refreshP.addActionListener(e->{try{pm.setRowCount(0);for(Object[] r:orders.deliveryPool(session.id()))pm.addRow(r);}catch(SQLException ex){error(ex);}});
        details.addActionListener(e->{int r=pt.getSelectedRow();if(r<0){message("Select an order first.");return;}try{int id=Integer.parseInt(pm.getValueAt(r,0).toString());JTextArea area=new JTextArea(orders.deliveryDetails(id));area.setEditable(false);area.setFont(new Font("Segoe UI",Font.PLAIN,14));area.setBorder(new EmptyBorder(12,12,12,12));JOptionPane.showMessageDialog(this,new JScrollPane(area),"Complete order details",JOptionPane.INFORMATION_MESSAGE);}catch(SQLException ex){error(ex);}});
        claim.addActionListener(e->{int r=pt.getSelectedRow();if(r<0){message("Select an order first.");return;}try{int id=Integer.parseInt(pm.getValueAt(r,0).toString());String full=orders.deliveryDetails(id);int confirm=JOptionPane.showConfirmDialog(this,new JScrollPane(new JTextArea(full,18,48)) ,"Review complete order before accepting",JOptionPane.YES_NO_OPTION,JOptionPane.INFORMATION_MESSAGE);if(confirm!=JOptionPane.YES_OPTION)return;orders.claimDelivery(id,session.id());message("Order accepted. Continue in MY ORDER HISTORY.");refreshP.doClick();refreshMRef[0].run();}catch(SQLException ex){message(ex.getMessage());}});
        decline.addActionListener(e->{int r=pt.getSelectedRow();if(r<0){message("Select an order first.");return;}try{orders.declineDelivery(Integer.parseInt(pm.getValueAt(r,0).toString()),session.id());message("Order declined. It will remain available to other BiteMates.");refreshP.doClick();}catch(SQLException ex){message(ex.getMessage());}});
        poolTab.add(pb,BorderLayout.NORTH);poolTab.add(new JScrollPane(pt),BorderLayout.CENTER);
        JPanel mineTab=new JPanel(new BorderLayout(10,10));mineTab.setOpaque(false);
        DefaultTableModel mm=new DefaultTableModel(new String[]{"ORDER","OUTLET","BUILDING","FLOOR","ROOM","TOTAL ₹","DELIVERY STATUS","CREATED","SHOP STATUS"},0){public boolean isCellEditable(int r,int c){return false;}};JTable mt=new JTable(mm);mt.setRowHeight(32);
        JButton refreshM=Style.button("REFRESH MY ORDER HISTORY",false),onWay=Style.button("ON WAY TO PICK UP",false),picked=Style.button("ORDER PICKED UP",false),out=Style.button("OUT FOR DELIVERY",true),camera=Style.button("OPEN CAMERA (DEMO)",false),delivered=Style.button("UPLOAD PHOTO & MARK DELIVERED",true);
        // Deliberate demo placeholder: this button is visual only and does not access the device camera.
        camera.setToolTipText("Camera integration is a demo placeholder. Use Upload Photo to attach delivery proof.");
        JPanel mb=new JPanel(new FlowLayout(FlowLayout.LEFT));mb.setOpaque(false);mb.add(refreshM);mb.add(onWay);mb.add(picked);mb.add(out);mb.add(camera);mb.add(delivered);
        Runnable loadMine=()->{try{mm.setRowCount(0);for(Object[] r:orders.assignedDeliveries(session.id()))mm.addRow(r);}catch(SQLException ex){error(ex);}};refreshMRef[0]=loadMine;
        refreshM.addActionListener(e->loadMine.run());
        onWay.addActionListener(e->updateMateStatus(mt,mm,"ON_WAY_TO_PICKUP",loadMine));picked.addActionListener(e->updateMateStatus(mt,mm,"PICKED_UP",loadMine));out.addActionListener(e->updateMateStatus(mt,mm,"OUT_FOR_DELIVERY",loadMine));
        delivered.addActionListener(e->{int r=mt.getSelectedRow();if(r<0){message("Select an order from your history first.");return;}String status=mm.getValueAt(r,6).toString();if(!status.equals("OUT_FOR_DELIVERY")){message("You can mark delivered only after selecting OUT FOR DELIVERY.");return;}JFileChooser chooser=new JFileChooser();chooser.setDialogTitle("Choose delivery proof photo");chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Images (JPG, PNG)","jpg","jpeg","png"));if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;try{java.io.File file=chooser.getSelectedFile();byte[] bytes=java.nio.file.Files.readAllBytes(file.toPath());if(bytes.length>8*1024*1024){message("Please choose an image smaller than 8 MB.");return;}orders.markDeliveredWithPhoto(Integer.parseInt(mm.getValueAt(r,0).toString()),session.id(),bytes,file.getName());message("Delivery proof uploaded. Order marked DELIVERED.");loadMine.run();}catch(Exception ex){message("Could not upload delivery proof: "+ex.getMessage());}});
        mineTab.add(mb,BorderLayout.NORTH);mineTab.add(new JScrollPane(mt),BorderLayout.CENTER);
        tabs.addTab("NEW ORDERS",poolTab);tabs.addTab("MY ORDER HISTORY",mineTab);parent.add(tabs,BorderLayout.CENTER);refreshP.doClick();loadMine.run();
    }
    private final Runnable[] refreshMRef=new Runnable[1];
    private void changeSelected(JTable table,DefaultTableModel model,String status){int r=table.getSelectedRow();if(r<0){message("Select an order first.");return;}try{int id=Integer.parseInt(model.getValueAt(r,0).toString());orders.updateOrderStatus(id,status);message("Order updated to "+status+".");}catch(SQLException ex){error(ex);}}
    private void updateMateStatus(JTable table,DefaultTableModel model,String status,Runnable refresh){int r=table.getSelectedRow();if(r<0){message("Select one of your assigned orders first.");return;}try{int id=Integer.parseInt(model.getValueAt(r,0).toString());orders.updateDeliveryStatus(id,session.id(),status);message("Delivery status updated to "+status.replace('_',' ')+".");refresh.run();}catch(SQLException ex){message(ex.getMessage());}}
    private void message(String s){JOptionPane.showMessageDialog(this,s,"QwikBite",JOptionPane.INFORMATION_MESSAGE);}private void error(SQLException e){JOptionPane.showMessageDialog(this,e.getMessage(),"Database error",JOptionPane.ERROR_MESSAGE);}
}
